(c?(y).P)[x:=w]^v=
\begin{cases}
c?(y).P,&y=x,\\
c?(y).(P[x:=w]^v),&y\ne x\land y\notin\operatorname{FVVal}_{Sess}(w),\\
c?(z).((P[y:=z]^v)[x:=w]^v),&y\ne x\land y\in\operatorname{FVVal}_{Sess}(w),
\end{cases}

(\mu Y.S)[X:=T]^S=
\begin{cases}
\mu Y.S,&Y=X,\\
\mu Y.(S[X:=T]^S),&Y\ne X\land Y\notin\operatorname{FV}_{Sess}^{S}(T),\\
\mu Z.((S[Y:=Z]^S)[X:=T]^S),&Y\ne X\land Y\in\operatorname{FV}_{Sess}^{S}(T),
\end{cases}
